// ---------------------------------------------------------------------------
// R_xlen_t — the 64-bit-safe length type used throughout Rinternals.h.
//
// The real Rinternals.h (lines 75 / 80):
//   #ifdef __LP64__
//     typedef ptrdiff_t R_xlen_t;    // 64-bit platforms
//   #else
//     typedef int       R_xlen_t;    // 32-bit platforms
//   #endif
//
// rpart operates only on lengths that fit in a 32-bit int; every
// LENGTH() result in the CSV is stored into a plain int variable.
// Typedef to int is therefore safe for the fake build and avoids
// introducing ptrdiff_t mismatch warnings.
//
// Guard: FAKE_R_XLEN_T_DEFINED prevents redefinition if a future
// header also provides this typedef.
// ---------------------------------------------------------------------------
#ifndef FAKE_R_XLEN_T_DEFINED
#define FAKE_R_XLEN_T_DEFINED

typedef int R_xlen_t;

#endif // FAKE_R_XLEN_T_DEFINED

// ---------------------------------------------------------------------------
