// Pattern P1/P2 — read the allocated capacity (same as length in fake).
inline R_xlen_t TRUELENGTH(SEXP s)  { return (R_xlen_t) s->length; }
inline R_xlen_t XTRUELENGTH(SEXP s) { return (R_xlen_t) s->length; }

#endif // FAKE_TRUELENGTH_DEFINED

