// --- ArenaFrame usage ---
// LENGTH itself performs no allocation and does not interact with the arena.
// The .Call-entry wrappers that enclose the LENGTH call sites DO require an
// ArenaFrame guard because the surrounding rpart/rpartexp2/xpred functions
// call ALLOC / R_alloc scratch allocations.
//
// Declare `ArenaFrame _frame;` as the first statement of any .Call-entry
// function whose body (directly or transitively) invokes arena-backed
// functions such as R_alloc or ALLOC from rpart's internal memory layer.
//
// Example for rpartexp2 (the simplest case):
//
//   #include "fake_arena.h"
//   extern "C" SEXP rpartexp2_entry(SEXP dtimes, SEXP eps) {
//       ArenaFrame _frame;   // arena scratch freed on exit (Invariant 2)
//       try {
//           return rpartexp2(dtimes, eps);
//           // Inside rpartexp2:
//           //   int n = LENGTH(dtimes);        => dtimes->length
//           //   SEXP keep = PROTECT(allocVector(INTSXP, n));  => heap
//           //   Rpartexp2(n, REAL(dtimes), asReal(eps), INTEGER(keep));
//           //   UNPROTECT(1);                  => no-op
//           //   return keep;                   => heap SEXP; outlives frame
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return nullptr;
//       }
//   }
//
// The SEXP return value (keep) is heap-allocated via malloc() inside
// allocVector and survives ArenaFrame destruction.  Python extracts data
// via INTEGER(keep) and calls free_sexp(keep) after copying into a numpy
// array.

